def main() -> None:
    os.makedirs(OUT, exist_ok=True)
    for key, svg in LOGOS.items():
        with open(os.path.join(OUT, key + ".svg"), "w", encoding="utf-8") as handle:
            handle.write(svg)
    print("wrote", len(LOGOS), "logos to", os.path.normpath(OUT))


if __name__ == "__main__":
    main()
